mapper.select:
select stock_price from inv_stock_warehouse
where warehouse_code=#{wrhCode,jdbcType=VARCHAR} and stock_code=#{stockCode,jdbcType=VARCHAR}
and goods_code=#{goodsCode,jdbcType=VARCHAR} and biz_org_code=#{bizOrgCode,jdbcType=VARCHAR}

select
    lsi.id
from
    logc_stock_info lsi
        inner join logc_warehouse_info lwi on lwi.id = lsi.warehouse_id and lwi.is_delete=0
where
    lsi.is_delete=0
    and lwi.warehouse_code=#{warehouseCode,jdbcType=VARCHAR}
    and lsi.stock_code=#{stockCode,jdbcType=VARCHAR}
    and (lsi.biz_org_code = #{bizOrgCode}
        or lsi.id in (select stock_id from logc_stock_org_auth where biz_org_code = #{bizOrgCode}))
    and (lwi.biz_org_code = #{bizOrgCode}
        or lwi.id in (select warehouse_id from logc_warehouse_org_auth where biz_org_code = #{bizOrgCode}))

select business_qty from inv_stock_warehouse
where warehouse_code=#{wrhCode,jdbcType=VARCHAR} and stock_code=#{stockCode,jdbcType=VARCHAR}
and goods_code=#{goodsCode,jdbcType=VARCHAR} and biz_org_code=#{bizOrgCode,jdbcType=VARCHAR}

select goods_code,business_qty from inv_stock_warehouse
where stock_code=#{stockCode} and goods_code in

    #{item}

and biz_org_code=#{bizOrgCode}
